CREATE TABLE IF NOT EXISTS admins (id BIGSERIAL PRIMARY KEY, username VARCHAR(80) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS customers (id BIGSERIAL PRIMARY KEY, name VARCHAR(160) NOT NULL, email VARCHAR(190) UNIQUE NOT NULL, phone VARCHAR(60), address TEXT, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products (id BIGSERIAL PRIMARY KEY, name VARCHAR(180) NOT NULL, category VARCHAR(100) DEFAULT 'Cadouri', description TEXT, price NUMERIC(10,2) NOT NULL DEFAULT 0, old_price NUMERIC(10,2), stock INT NOT NULL DEFAULT 0, image VARCHAR(500), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders (id BIGSERIAL PRIMARY KEY, customer_id BIGINT REFERENCES customers(id) ON DELETE SET NULL, customer_name VARCHAR(160) NOT NULL, email VARCHAR(190), phone VARCHAR(60) NOT NULL, address TEXT, details TEXT, total NUMERIC(10,2) NOT NULL DEFAULT 0, status VARCHAR(30) NOT NULL DEFAULT 'Nouă' CHECK (status IN ('Nouă','Confirmată','În lucru','Expediată','Livrată','Finalizată','Anulată')), created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items (id BIGSERIAL PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id BIGINT REFERENCES products(id) ON DELETE SET NULL, product_name VARCHAR(180) NOT NULL, qty INT NOT NULL DEFAULT 1, price NUMERIC(10,2) NOT NULL, personalization TEXT, personalization_image TEXT);
INSERT INTO products(name,category,description,price,old_price,stock,image) SELECT 'Cană personalizată','Căni','Adaugă fotografia și mesajul tău.',39.90,49.90,25,'assets/images/magneti-botez-01.webp' WHERE NOT EXISTS (SELECT 1 FROM products);
INSERT INTO products(name,category,description,price,old_price,stock,image) SELECT 'Pernă personalizată','Perne','Cadou moale cu fotografie și text.',59.90,69.90,18,'assets/images/magneti-botez-02.webp' WHERE NOT EXISTS (SELECT 1 FROM products WHERE name='Pernă personalizată');
INSERT INTO products(name,category,description,price,old_price,stock,image) SELECT 'Tablou personalizat','Tablouri','Transformă o fotografie într-un decor special.',89.90,109.90,12,'assets/images/magneti-botez-03.webp' WHERE NOT EXISTS (SELECT 1 FROM products WHERE name='Tablou personalizat');
